    async def lookup_users(
        self,
        *,
        type: str,
        field: str,
        value: typing.Optional[str] = OMIT,
        from_: typing.Optional[str] = OMIT,
        to: typing.Optional[str] = OMIT,
        prefix: typing.Optional[str] = OMIT,
        start_from: typing.Optional[str] = OMIT,
        limit: typing.Optional[int] = OMIT,
        order: typing.Optional[IdentityLookupRequestOrder] = OMIT,
        request_options: typing.Optional[RequestOptions] = None,
    ) -> UserPage:
        """
        Looks up users by a schema lookup field, with the query criteria carried in the request body rather than the URL. Use this when looking up by a sensitive (blind-indexed) field: the value is blind-indexed server-side and never appears in the URL, request logs, or proxies. The query semantics are identical to the GET /v1/users lookup, which rejects sensitive-field values and directs you here. Returns a page in the `{data, nextCursor}` envelope. Requires the `users:r` scope.

        Parameters
        ----------
        type : str
            The identity schema type whose lookup fields you are querying (for example, `person_v1`).

        field : str
            Name of the lookup field declared on the schema. For a field marked sensitive, this body variant is required (the GET variant rejects looking up by a sensitive value).

        value : typing.Optional[str]
            Exact value to match. Mutually exclusive with `from`/`to` and `prefix`.

        from_ : typing.Optional[str]
            Inclusive lower bound for a range lookup (requires `to`; supported only on range-enabled, non-sensitive fields). Mutually exclusive with `value` and `prefix`.

        to : typing.Optional[str]
            Inclusive upper bound for a range lookup (requires `from`).

        prefix : typing.Optional[str]
            Prefix to match (supported only on range-enabled string fields). Mutually exclusive with `value` and `from`/`to`.

        start_from : typing.Optional[str]
            Pagination cursor — pass the `nextCursor` returned by the previous page.

        limit : typing.Optional[int]
            Maximum number of results to return per page (1–100; defaults to 20).

        order : typing.Optional[IdentityLookupRequestOrder]
            Sort direction for the returned results: `asc` (default) or `desc`.

        request_options : typing.Optional[RequestOptions]
            Request-specific configuration.

        Returns
        -------
        UserPage
            A page of matching users in the `{data, nextCursor}` envelope.

        Examples
        --------
        import asyncio

        from vectros import AsyncVectrosApi

        client = AsyncVectrosApi(
            token="YOUR_TOKEN",
            base_url="https://yourhost.com/path/to/api",
        )


        async def main() -> None:
            await client.identity.lookup_users(
                type="person_v1",
                field="ssn",
            )


        asyncio.run(main())
        """
        _response = await self._raw_client.lookup_users(
            type=type,
            field=field,
            value=value,
            from_=from_,
            to=to,
            prefix=prefix,
            start_from=start_from,
            limit=limit,
            order=order,
            request_options=request_options,
        )
        return _response.data

    async def get_user_versions(
        self,
        id: str,
        *,
        start_from: typing.Optional[str] = None,
        request_options: typing.Optional[RequestOptions] = None,
    ) -> ModelDataVersionPage:
        """
        Returns the audit trail of changes to a user, most recent first. Identity history is always recorded and always available. Sensitive field values are redacted in every historical version. Returns a page in the `{data, nextCursor}` envelope. Requires the `users:r` scope.

        Parameters
        ----------
        id : str
            The Vectros-assigned UUID of the user.

        start_from : typing.Optional[str]
            Pagination cursor. Pass the ID of the last version from the previous page to fetch the next page.

        request_options : typing.Optional[RequestOptions]
            Request-specific configuration.

        Returns
        -------
        ModelDataVersionPage
            A page of historical versions in the `{data, nextCursor}` envelope.

        Examples
        --------
        import asyncio

        from vectros import AsyncVectrosApi

        client = AsyncVectrosApi(
            token="YOUR_TOKEN",
            base_url="https://yourhost.com/path/to/api",
        )


        async def main() -> None:
            await client.identity.get_user_versions(
                id="id",
            )


        asyncio.run(main())
        """
        _response = await self._raw_client.get_user_versions(id, start_from=start_from, request_options=request_options)
        return _response.data
